365	  async function assertCanCreateAgentsForCompany(req: Request, companyId: string) {
366	    assertCompanyAccess(req, companyId);
367	    if (req.actor.type === "board") {
368	      if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) return null;
369	      const allowed = await access.canUser(companyId, req.actor.userId, "agents:create");
370	      if (!allowed) {
371	        throw forbidden("Missing permission: agents:create");
372	      }
373	      return null;
374	    }
375	    if (!req.actor.agentId) throw forbidden("Agent authentication required");
376	    const actorAgent = await svc.getById(req.actor.agentId);
377	    if (!actorAgent || actorAgent.companyId !== companyId) {
378	      throw forbidden("Agent key cannot access another company");
379	    }
380	    const allowedByGrant = await access.hasPermission(companyId, "agent", actorAgent.id, "agents:create");
381	    if (!allowedByGrant && !canCreateAgents(actorAgent)) {
382	      throw forbidden("Missing permission: can create agents");
383	    }
384	    return actorAgent;
385	  }
