427	  async function buildSkippedWakeupResponse(
428	    agent: NonNullable<Awaited<ReturnType<typeof svc.getById>>>,
429	    payload: Record<string, unknown> | null | undefined,
430	  ) {
431	    const issueId = typeof payload?.issueId === "string" && payload.issueId.trim() ? payload.issueId : null;
432	    if (!issueId) {
433	      return {
434	        status: "skipped" as const,
435	        reason: "wakeup_skipped",
436	        message: "Wakeup was skipped.",
437	        issueId: null,
438	        executionRunId: null,
439	        executionAgentId: null,
440	        executionAgentName: null,
441	      };
442	    }
443	
444	    const issue = await db
445	      .select({
446	        id: issuesTable.id,
447	        executionRunId: issuesTable.executionRunId,
448	      })
449	      .from(issuesTable)
450	      .where(and(eq(issuesTable.id, issueId), eq(issuesTable.companyId, agent.companyId)))
451	      .then((rows) => rows[0] ?? null);
452	
453	    if (!issue?.executionRunId) {
454	      return {
455	        status: "skipped" as const,
456	        reason: "wakeup_skipped",
457	        message: "Wakeup was skipped.",
458	        issueId,
459	        executionRunId: null,
460	        executionAgentId: null,
461	        executionAgentName: null,
462	      };
463	    }
464	
465	    const executionRun = await heartbeat.getRun(issue.executionRunId);
466	    if (!executionRun || (executionRun.status !== "queued" && executionRun.status !== "running")) {
467	      return {
468	        status: "skipped" as const,
469	        reason: "wakeup_skipped",
470	        message: "Wakeup was skipped.",
471	        issueId,
472	        executionRunId: issue.executionRunId,
473	        executionAgentId: null,
474	        executionAgentName: null,
475	      };
476	    }
477	
478	    const executionAgent = await svc.getById(executionRun.agentId);
479	    const executionAgentName = executionAgent?.name ?? null;
480	
481	    return {
482	      status: "skipped" as const,
483	      reason: "issue_execution_deferred",
484	      message: executionAgentName
485	        ? `Wakeup was deferred because this issue is already being executed by ${executionAgentName}.`
486	        : "Wakeup was deferred because this issue already has an active execution run.",
487	      issueId,
488	      executionRunId: executionRun.id,
489	      executionAgentId: executionRun.agentId,
490	      executionAgentName,
491	    };
492	  }
