506	
507	    if (actorAgent.id === targetAgent.id) return;
508	    if (actorAgent.role === "ceo") return;
509	    const allowedByGrant = await access.hasPermission(
510	      targetAgent.companyId,
511	      "agent",
512	      actorAgent.id,
513	      "agents:create",
514	    );
515	    if (allowedByGrant || canCreateAgents(actorAgent)) return;
516	    throw forbidden("Only CEO or agent creators can modify other agents");
517	  }
